INSERT INTO toolboxes_inventory.toolbox_sections (toolbox_id, name, section_type, position_order)
SELECT DISTINCT ON (toolbox_id, section_name)
    toolbox_id,
    section_name,
    CASE
        WHEN section_name ILIKE 'GAVETA%' THEN 'gaveta'
        WHEN section_name ILIKE 'TABLERO%' THEN 'tablero'
        WHEN section_name ILIKE 'TAPA%' THEN 'tapa'
        WHEN section_name ILIKE 'PUERTA%' THEN 'puerta'
        ELSE 'other'
    END,
    MIN(position_order) OVER (PARTITION BY toolbox_id, section_name)
FROM raw_items
WHERE section_name IS NOT NULL
ORDER BY toolbox_id, section_name, position_order
ON CONFLICT (toolbox_id, name) DO NOTHING;

