INSERT INTO toolboxes_inventory.toolbox_groups (section_id, name, position_order)
SELECT DISTINCT ON (s.id, r.group_name)
    s.id,
    r.group_name,
    MIN(r.position_order) OVER (PARTITION BY s.id, r.group_name)
FROM raw_items r
JOIN toolboxes_inventory.toolbox_sections s
    ON s.toolbox_id = r.toolbox_id
   AND s.name = r.section_name
WHERE r.group_name IS NOT NULL
AND TRIM(r.group_name) <> ''
ORDER BY s.id, r.group_name, 3
ON CONFLICT (section_id, name) DO NOTHING;

