INSERT INTO toolboxes_inventory.tool_variants (
    tool_id, variant_name, spanish_description, french_description, drive_size, measurement, length_type, impact, brand
)
SELECT DISTINCT
    
CASE
    WHEN content ILIKE '%guante%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Guantes de uso diario')
    WHEN content ILIKE '%recipiente%' OR content ILIKE '%charola%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Recipiente con iman')
    WHEN content ILIKE '%funnel%' OR content ILIKE '%embudo%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name IN ('Embudo plastico', 'Embudo metalico ajustable') ORDER BY id LIMIT 1)
    WHEN content ILIKE '%stillson%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Llave Stillson')
    WHEN content ILIKE '%cangrejo%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Llave de cangrejo')
    WHEN content ILIKE '%llave de extension%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Llave de extension')
    WHEN content ILIKE '%llave%' AND (content ILIKE '%ratch%' OR content ILIKE '%rath%' OR content ILIKE '%matraca%') THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Llave con ratch')
    WHEN content ILIKE '%llave%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Llave')
    WHEN content ILIKE '%desarmador%' AND content ILIKE '%philips%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Desarmador Philips')
    WHEN content ILIKE '%desarmador%' AND content ILIKE '%plano%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Desarmador plano')
    WHEN content ILIKE '%desarmador%' AND content ILIKE '%tipo s%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Desarmador tipo S')
    WHEN content ILIKE '%desarmador%' AND content ILIKE '%palanca%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Desarmador de palanca')
    WHEN content ILIKE '%desarmador%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Desarmador plano')
    WHEN content ILIKE '%copa%' AND content ILIKE '%impact%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Copa de impacto')
    WHEN content ILIKE '%copa%' AND (content ILIKE '%larga%' OR content ILIKE '%largo%') THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Copa larga')
    WHEN content ILIKE '%copa%' AND (content ILIKE '%corta%' OR content ILIKE '%corto%') THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Copa corta')
    WHEN content ILIKE '%copa%' OR content ILIKE '%socket%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Copa estandar')
    WHEN content ILIKE '%ratch neumatico%' OR content ILIKE '%ratchet neumatico%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Ratch neumatico')
    WHEN content ILIKE '%ratch%' OR content ILIKE '%ratchet%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Ratch')
    WHEN content ILIKE '%extension%' OR content ILIKE '%extencion%' OR content ILIKE '%exstension%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Extension')
    WHEN content ILIKE '%codo%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Codo')
    WHEN content ILIKE '%convertidor%' OR content ILIKE '%convetidor%' OR content ILIKE '%convertido%' OR content ILIKE '%adaptador%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Convertidor')
    WHEN content ILIKE '%alicate%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Alicate')
    WHEN content ILIKE '%pinza%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Pinza')
    WHEN content ILIKE '%tenaza%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Tenaza')
    WHEN content ILIKE '%corta cable%' OR content ILIKE '%corta cables%' OR content ILIKE '%cortador de cable%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Corta cables')
    WHEN content ILIKE '%vise grip%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Vise grip')
    WHEN content ILIKE '%martillo%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Martillo')
    WHEN content ILIKE '%mazo%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Mazo')
    WHEN content ILIKE '%punzon%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Punzon')
    WHEN content ILIKE '%cincel%' OR content ILIKE '%cilsel%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Cincel')
    WHEN content ILIKE '%lima%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Lima')
    WHEN content ILIKE '%cepillo de alambre%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Cepillo de alambre')
    WHEN content ILIKE '%vernier%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Vernier')
    WHEN content ILIKE '%metro%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Metro')
    WHEN content ILIKE '%multimetro%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Multimetro')
    WHEN content ILIKE '%antorcha%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Antorcha de butano')
    WHEN content ILIKE '%pistola%aire%' OR content ILIKE '%sopletear%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Pistola de aire')
    WHEN content ILIKE '%saca filtro%' OR content ILIKE '%sacafiltro%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Saca filtro')
    WHEN content ILIKE '%iman%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Iman')
    WHEN content ILIKE '%camilla%' THEN (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Camilla')
    ELSE (SELECT id FROM toolboxes_inventory.tools WHERE spanish_name = 'Otro')
END
 AS tool_id,
    content,
    content,
    NULL,
    CASE
        WHEN content ~* '1/4' THEN '1/4'
        WHEN content ~* '3/8' THEN '3/8'
        WHEN content ~* '1/2' THEN '1/2'
        WHEN content ~* '3/4' THEN '3/4'
        WHEN content ~* '1"' THEN '1'
        ELSE NULL
    END,
    (regexp_match(content, '(T{1,2}[0-9]+|TP[0-9]+|PH[0-9]+|SQ[0-9]+|H[0-9]+/?[0-9]*|[0-9]+(\.[0-9]+)?mm|[0-9]+/[0-9]+|[0-9]+" ?[0-9]*/?[0-9]*)', 'i'))[1],
    CASE
        WHEN content ILIKE '%corto%' OR content ILIKE '%corta%' THEN 'corto'
        WHEN content ILIKE '%mediano%' OR content ILIKE '%mediana%' THEN 'mediano'
        WHEN content ILIKE '%largo%' OR content ILIKE '%larga%' THEN 'largo'
        WHEN content ILIKE '%grande%' THEN 'grande'
        WHEN content ILIKE '%pequeno%' OR content ILIKE '%pequeño%' OR content ILIKE '%small size%' THEN 'pequeno'
        ELSE NULL
    END,
    CASE WHEN content ILIKE '%impacto%' OR content ILIKE '%impact%' THEN true ELSE false END,
    CASE
        WHEN content ILIKE '%Milwaukee%' THEN 'Milwaukee'
        WHEN content ILIKE '%Stanley%' THEN 'Stanley'
        WHEN content ILIKE '%Mastercraft%' THEN 'Mastercraft'
        WHEN content ILIKE '%Maximum%' THEN 'Maximum'
        WHEN content ILIKE '%OYECOVE%' THEN 'OYECOVE'
        WHEN content ILIKE '%De Walt%' OR content ILIKE '%Dewalt%' THEN 'DeWalt'
        WHEN content ILIKE '%Husky%' THEN 'Husky'
        WHEN content ILIKE '%Jet%' THEN 'JET'
        ELSE NULL
    END
FROM raw_items
WHERE content IS NOT NULL
AND TRIM(content) <> ''
AND content NOT ILIKE '%espacio vacio%'
AND content NOT ILIKE '%espacio libre%'
ON CONFLICT (tool_id, variant_name) DO NOTHING;

