INSERT INTO toolboxes_inventory.toolbox_items (
    toolbox_id, section_id, group_id, tool_variant_id, raw_description, expected_quantity, actual_quantity, status, status_note, position_order
)
SELECT
    r.toolbox_id,
    s.id,
    g.id,
    tv.id,
    r.content,
    CASE
        WHEN r.quantity = 0 AND (r.content ILIKE '%espacio vacio%' OR r.content ILIKE '%espacio libre%') THEN 0
        WHEN r.quantity = 0 THEN 1
        ELSE COALESCE(r.quantity, 1)
    END,
    CASE
        WHEN r.quantity = 0 THEN 0
        WHEN r.status_note ILIKE '%espacio vacio%' THEN 0
        WHEN r.status_note ILIKE '%falta%' THEN 0
        WHEN r.status_note ILIKE '%no hay%' THEN 0
        ELSE COALESCE(r.quantity, 1)
    END,
    CASE
        WHEN r.content ILIKE '%espacio vacio%' OR r.content ILIKE '%espacio libre%' THEN 'empty_space'
        WHEN r.status_note ILIKE '%no funciona%' THEN 'broken'
        WHEN r.status_note ILIKE '%falta%' OR r.status_note ILIKE '%no hay%' THEN 'missing'
        WHEN r.status_note ILIKE '%pendiente%' THEN 'pending'
        WHEN r.quantity = 0 THEN 'missing'
        ELSE 'ok'
    END,
    r.status_note,
    r.position_order
FROM raw_items r
JOIN toolboxes_inventory.toolbox_sections s
    ON s.toolbox_id = r.toolbox_id
   AND s.name = r.section_name
LEFT JOIN toolboxes_inventory.toolbox_groups g
    ON g.section_id = s.id
   AND g.name = r.group_name
LEFT JOIN LATERAL (
    SELECT tv2.id
    FROM toolboxes_inventory.tool_variants tv2
    WHERE LOWER(REGEXP_REPLACE(tv2.variant_name, '\s+', ' ', 'g')) = LOWER(REGEXP_REPLACE(TRIM(r.content), '\s+', ' ', 'g'))
    ORDER BY tv2.id
    LIMIT 1
) tv ON true
WHERE r.content IS NOT NULL
AND TRIM(r.content) <> ''
ON CONFLICT (toolbox_id, position_order) DO UPDATE SET
    section_id = EXCLUDED.section_id,
    group_id = EXCLUDED.group_id,
    tool_variant_id = EXCLUDED.tool_variant_id,
    raw_description = EXCLUDED.raw_description,
    expected_quantity = EXCLUDED.expected_quantity,
    actual_quantity = EXCLUDED.actual_quantity,
    status = EXCLUDED.status,
    status_note = EXCLUDED.status_note;

SELECT status, COUNT(*) FROM toolboxes_inventory.toolbox_items WHERE toolbox_id = 6 GROUP BY status ORDER BY status;
SELECT COUNT(*) AS unmatched_non_empty_space FROM toolboxes_inventory.toolbox_items WHERE toolbox_id = 6 AND tool_variant_id IS NULL AND status <> 'empty_space';
COMMIT;
